#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);const auto args=app.arguments();if(args.contains("-version-full")){std::cout<<"blastn: controlled-fixture (not installed BLAST+)\nblastp: controlled-fixture (not installed BLAST+)\n";return 0;}if(args.contains("fixture_stall")){std::cerr<<"Controlled client: waiting without output"<<std::endl;return app.exec();}const int at=args.indexOf("-query");if(at<0||at+1>=args.size()||!args.contains("-remote")||!args.contains("-outfmt"))return 2;QFile file(args[at+1]);if(!file.open(QIODevice::ReadOnly))return 3;QString id,sequence;QJsonArray reports;auto emitReport=[&]{if(id.isEmpty())return;QJsonObject hsp{{"bit_score",99},{"evalue",1e-15},{"identity",sequence.size()},{"align_len",sequence.size()},{"query_from",1},{"query_to",sequence.size()},{"hit_from",1},{"hit_to",sequence.size()},{"gaps",0}};QJsonObject hit{{"description",QJsonArray{QJsonObject{{"accession","TEST.1"},{"title","Toolkit fixture"}}}},{"hsps",QJsonArray{hsp}}};QJsonObject search{{"query_title",id},{"query_len",sequence.size()},{"hits",QJsonArray{hit}}};QJsonObject results{{"search",search}},report{{"results",results}};reports.append(QJsonObject{{"report",report}});};for(const auto& line:QString::fromLatin1(file.readAll()).split('\n')){if(line.startsWith('>')){emitReport();id=line.mid(1);sequence.clear();}else sequence+=line.trimmed();}emitReport();std::cout<<QJsonDocument(QJsonObject{{"BlastOutput2",reports}}).toJson().constData();return 0;}
